# WReparse - path semantics
# Canonicalisation, directory-boundary containment, and link-target resolution.
# Part of the WReparse implementation. See the contract under docs/
#
# Canonical form used for every comparison and for the report:
#   * full (rooted) path with '.' and '..' collapsed and '/' folded to '\'
#   * no trailing directory separator, except for a volume root ('C:\')
#   * original casing preserved - never lower-cased, because the report must
#     show the on-disk spelling the operator can act on
# Only Get-WReparseCanonicalPath / Test-WReparseWithinRoot /
# Resolve-WReparseLinkTarget are exported (see WReparse.psm1); everything else
# in this file is module-private.

$script:WReparseDirectorySeparator = [string][char]0x5C   # '\'
$script:WReparseAltSeparator = [string][char]0x2F         # '/'
$script:WReparseSeparatorChars = @([char]0x5C, [char]0x2F)

function Get-WReparseCanonicalPath {
    # Contract section 5.1. Returns $null when the argument cannot be turned
    # into an absolute path at all (empty string, illegal characters, ...);
    # callers translate that into the 'invalid_argument' error code.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path
    )
    if ([string]::IsNullOrEmpty($Path)) { return $null }

    $full = $null
    try {
        # GetFullPath collapses '.' / '..' segments, folds '/' into '\' and
        # resolves relative input against the process working directory. It
        # throws ArgumentException on input that is not a usable path at all.
        $full = [System.IO.Path]::GetFullPath($Path)
    }
    catch {
        return $null
    }
    if ([string]::IsNullOrEmpty($full)) { return $null }

    $trimmed = $full.TrimEnd($script:WReparseSeparatorChars)
    if ([string]::IsNullOrEmpty($trimmed)) {
        # '\'-only input that survived GetFullPath: keep the root form.
        return $full
    }
    # A volume root keeps its separator ('C:\'), everything else loses it.
    if ($trimmed.Length -eq 2 -and $trimmed[1] -eq ':') {
        return ($trimmed + $script:WReparseDirectorySeparator)
    }
    # A UNC share root keeps the '\\server\share' form rather than collapsing
    # down to the server component.
    if ($trimmed.StartsWith($script:WReparseDirectorySeparator + $script:WReparseDirectorySeparator, [System.StringComparison]::Ordinal)) {
        $uncParts = @($trimmed.Split([char]0x5C))
        if ($uncParts.Count -le 4) { return $trimmed }
    }
    return $trimmed
}

function Get-WReparseRootPrefix {
    # Directory-boundary prefix of a canonical root: the root plus one
    # separator, unless the root already ends with one (volume root).
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$CanonicalRoot)
    if ([string]::IsNullOrEmpty($CanonicalRoot)) { return $script:WReparseDirectorySeparator }
    if ($CanonicalRoot.EndsWith($script:WReparseDirectorySeparator, [System.StringComparison]::Ordinal)) {
        return $CanonicalRoot
    }
    return ($CanonicalRoot + $script:WReparseDirectorySeparator)
}

function Test-WReparseWithinRoot {
    # Contract section 5.2: containment is decided on DIRECTORY boundaries, so
    # 'C:\root2' is NOT inside 'C:\root' even though the raw string starts with
    # it. Comparison is ordinal and case-insensitive (Windows path semantics),
    # never culture-aware. The root itself counts as inside.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root
    )
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Root)) { return $false }

    $candidate = Get-WReparseCanonicalPath -Path $Path
    $rootCanonical = Get-WReparseCanonicalPath -Path $Root
    if ($null -eq $candidate -or $null -eq $rootCanonical) { return $false }

    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($candidate, $rootCanonical)) { return $true }

    $prefix = Get-WReparseRootPrefix -CanonicalRoot $rootCanonical
    return [bool]$candidate.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

function Get-WReparseRelativePath {
    # Relative path of a scanned entry with respect to the scan root, using the
    # Windows separator. The root itself yields '.'. Casing is preserved.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$FullPath,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root
    )
    if ([string]::IsNullOrEmpty($FullPath)) { return '.' }

    $candidate = Get-WReparseCanonicalPath -Path $FullPath
    $rootCanonical = Get-WReparseCanonicalPath -Path $Root
    if ($null -eq $candidate) { return $FullPath }
    if ($null -eq $rootCanonical) { return $candidate }

    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($candidate, $rootCanonical)) { return '.' }

    $prefix = Get-WReparseRootPrefix -CanonicalRoot $rootCanonical
    if ($candidate.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $candidate.Substring($prefix.Length)
    }
    return $candidate
}

function Resolve-WReparseLinkTarget {
    # Contract section 5.3. A relative target is resolved against the directory
    # that CONTAINS the link - never against the process working directory and
    # never against the scan root. Unresolvable input yields $null.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$LinkFullPath,
        [AllowNull()][AllowEmptyString()][string]$RawTarget
    )
    if ([string]::IsNullOrWhiteSpace($RawTarget)) { return $null }
    if ([string]::IsNullOrWhiteSpace($LinkFullPath)) { return $null }

    $linkCanonical = Get-WReparseCanonicalPath -Path $LinkFullPath
    if ($null -eq $linkCanonical) { return $null }

    $linkDirectory = [System.IO.Path]::GetDirectoryName($linkCanonical)
    if ([string]::IsNullOrEmpty($linkDirectory)) {
        # The link sits directly in a volume root: 'C:\' -> GetDirectoryName
        # returns $null, so fall back to the root itself.
        $linkDirectory = [System.IO.Path]::GetPathRoot($linkCanonical)
    }
    if ([string]::IsNullOrEmpty($linkDirectory)) { return $null }

    $candidate = $null
    try {
        if ([System.IO.Path]::IsPathRooted($RawTarget)) {
            # Absolute target: normalise as-is.
            $candidate = [System.IO.Path]::GetFullPath($RawTarget)
        }
        else {
            # Relative target: join onto the link's own directory, then let
            # GetFullPath collapse '.' / '..' segments.
            $joined = [System.IO.Path]::Combine($linkDirectory, $RawTarget.TrimEnd($script:WReparseSeparatorChars))
            $candidate = [System.IO.Path]::GetFullPath($joined)
        }
    }
    catch {
        return $null
    }
    if ([string]::IsNullOrEmpty($candidate)) { return $null }
    return Get-WReparseCanonicalPath -Path $candidate
}

function Compare-WReparsePath {
    # Stable ordering key (contract section 6): ordinal case-insensitive
    # primary key, ordinal case-sensitive tie-break. Neither comparer is
    # culture-aware, so the report cannot be reshuffled by the host locale
    # (a culture-aware sort would push 'A' with a diacritic before ASCII 'Z').
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Left,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Right
    )
    $primary = [System.StringComparer]::OrdinalIgnoreCase.Compare($Left, $Right)
    if ($primary -ne 0) { return $primary }
    return [System.StringComparer]::Ordinal.Compare($Left, $Right)
}

function Test-WReparseInAncestry {
    # Ordinal-ignore-case membership test for the per-branch ancestor chain
    # used by cycle detection.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][string[]]$Chain,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Value
    )
    foreach ($entry in $Chain) {
        if ([string]::IsNullOrEmpty($entry)) { continue }
        if ([System.StringComparer]::OrdinalIgnoreCase.Equals($entry, $Value)) { return $true }
    }
    return $false
}

# WReparse - directory walker
# Safe directory enumeration: reparse classification, containment, cycle and
# depth control. Part of the WReparse implementation.
#
# Nothing in this file is exported; the module surface is fixed by the contract
# (see WReparse.psm1).

# FILE_ATTRIBUTE_REPARSEPOINT (0x400). This is the ONLY reliable marker of a
# reparse point: a hard link reports LinkType 'HardLink' yet carries no
# reparse attribute, and must therefore be recorded as a plain File.
$script:WReparseAttributeReparsePoint = [int][System.IO.FileAttributes]::ReparsePoint

function Get-WReparseMemberValue {
    # Null-safe property lookup; enumeration results are FileSystemInfo but the
    # provider is free to attach (or omit) note properties such as LinkType.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$InputObject,
        [Parameter(Mandatory = $true)][string]$Name
    )
    if ($null -eq $InputObject) { return $null }
    $property = $InputObject.PSObject.Properties[$Name]
    if ($null -eq $property) { return $null }
    return $property.Value
}

function Test-WReparseIsReparsePoint {
    # Contract section 3.1: classification depends solely on the
    # FILE_ATTRIBUTE_REPARSE_POINT attribute bit. LinkType is NOT consulted
    # here - a hard link has a LinkType but is an ordinary file.
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)]$Item)
    $attributes = Get-WReparseMemberValue -InputObject $Item -Name 'Attributes'
    if ($null -eq $attributes) { return $false }
    $flags = 0
    try { $flags = [int]$attributes }
    catch { return $false }
    return ((($flags -band $script:WReparseAttributeReparsePoint) -ne 0))
}

function Get-WReparseReparseKind {
    # Maps the provider link type onto the contract vocabulary. Only entries
    # that carry the reparse attribute reach this function.
    [CmdletBinding()]
    param([AllowNull()][AllowEmptyString()][string]$LinkType)
    if ([string]::IsNullOrWhiteSpace($LinkType)) { return $script:WReparseReparseKindUnknown }
    $trimmed = $LinkType.Trim()
    if ($trimmed -eq $script:WReparseReparseKindSymbolicLink) { return $script:WReparseReparseKindSymbolicLink }
    if ($trimmed -eq $script:WReparseReparseKindJunction) { return $script:WReparseReparseKindJunction }
    if ($trimmed -eq $script:WReparseReparseKindMountPoint) { return $script:WReparseReparseKindMountPoint }
    return $script:WReparseReparseKindUnknown
}

function Get-WReparseRawTarget {
    # The provider exposes .Target as a collection (a reparse point may carry
    # several substitutions) and PowerShell unrolls a single-element array into
    # the element itself. The contract defines Target as ONE string, so the
    # first substitution is taken and explicitly coerced; the type therefore
    # never changes with the number of targets.
    [CmdletBinding()]
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [string]) {
        if ($Value.Length -eq 0) { return $null }
        return $Value
    }
    $items = @($Value)
    foreach ($element in $items) {
        if ($null -eq $element) { continue }
        $text = [string]$element
        if ($text.Length -gt 0) { return $text }
    }
    return $null
}

function Test-WReparsePathExists {
    # Read-only existence probe that never throws and never goes through the
    # provider pipeline.
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    if ([System.IO.Directory]::Exists($Path)) { return $true }
    return [bool][System.IO.File]::Exists($Path)
}

function Test-WReparseIsDirectory {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    return [bool][System.IO.Directory]::Exists($Path)
}

function Add-WReparseError {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Code,
        [Parameter(Mandatory = $true)][string]$Message
    )
    [void]$State.Errors.Add((New-WReparseError -RelativePath $RelativePath -Code $Code -Message $Message))
}

function Invoke-WReparseDirectoryWalk {
    # Enumerates one physical directory and emits it into $State. $RealDirectory
    # is the location actually read; $VirtualDirectory is the path the entry is
    # REPORTED under. They only differ when a reparse point was followed, in
    # which case the children keep the LINK path as their prefix (contract
    # section 4.2) instead of the real target path.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$RealDirectory,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$VirtualDirectory,
        [Parameter(Mandatory = $true)][int]$Depth,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][string[]]$Ancestry,
        [Parameter(Mandatory = $true)][hashtable]$State
    )

    # Contract section 4.3: a directory whose depth already equals -MaxDepth is
    # not enumerated and yields one 'too_deep' error. Depth starts at 0 for the
    # scan root, so -MaxDepth 0 (and any negative value, clamped to 0) stops at
    # the root itself.
    if ($Depth -ge $State.MaxDepth) {
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'too_deep' `
            -Message ("Depth limit of {0} reached; children were not enumerated." -f $State.MaxDepth)
        return
    }

    $children = @()
    try {
        $children = @(Get-ChildItem -LiteralPath $RealDirectory -Force -ErrorAction Stop)
    }
    catch {
        # Contract section 4.4: one failing directory never aborts the scan.
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'access_denied' `
            -Message 'The directory could not be enumerated.'
        return
    }

    foreach ($child in $children) {
        $childDepth = $Depth + 1
        $childName = [string](Get-WReparseMemberValue -InputObject $child -Name 'Name')
        $realChild = [string](Get-WReparseMemberValue -InputObject $child -Name 'FullName')
        if ([string]::IsNullOrEmpty($childName)) { continue }
        $virtualChild = Join-Path -Path $VirtualDirectory -ChildPath $childName
        $relative = Get-WReparseRelativePath -FullPath $virtualChild -Root $State.Root

        if (Test-WReparseIsReparsePoint -Item $child) {
            $linkType = [string](Get-WReparseMemberValue -InputObject $child -Name 'LinkType')
            $rawTarget = Get-WReparseRawTarget -Value (Get-WReparseMemberValue -InputObject $child -Name 'Target')

            # ResolvedTarget / InScope are always reported (they are pure path
            # arithmetic), but the follow-only error codes are only produced in
            # follow mode (contract section 7).
            $resolved = $null
            if ($null -ne $rawTarget) {
                $resolved = Resolve-WReparseLinkTarget -LinkFullPath $realChild -RawTarget $rawTarget
            }
            $inScope = $false
            if ($null -ne $resolved) {
                $inScope = Test-WReparseWithinRoot -Path $resolved -Root $State.Root
            }

            [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative `
                    -Kind $script:WReparseKindReparse `
                    -ReparseKind (Get-WReparseReparseKind -LinkType $linkType) `
                    -Target $rawTarget -ResolvedTarget $resolved -InScope $inScope `
                    -Depth $childDepth -Size 0))

            if (-not $State.Follow) {
                # Default mode: register the entry, never descend, count it as
                # skipped (contract section 4.1).
                $State.Skipped++
                continue
            }

            if ($null -eq $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target could not be resolved.'
                continue
            }
            if (-not (Test-WReparsePathExists -Path $resolved)) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target does not exist.'
                continue
            }
            if (Test-WReparseInAncestry -Chain $Ancestry -Value $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'cycle' `
                    -Message 'The reparse target is already an ancestor on this branch.'
                continue
            }
            if (Test-WReparseIsDirectory -Path $resolved) {
                # Descend through the link, reporting children under the LINK
                # path, not under the target path.
                Invoke-WReparseDirectoryWalk -RealDirectory $resolved -VirtualDirectory $virtualChild `
                    -Depth $childDepth -Ancestry ($Ancestry + $resolved) -State $State
            }
            # A link whose target is a file contributes no children at all.
            continue
        }

        $isContainer = [bool](Get-WReparseMemberValue -InputObject $child -Name 'PSIsContainer')
        $size = [long]0
        if (-not $isContainer) {
            $length = Get-WReparseMemberValue -InputObject $child -Name 'Length'
            if ($null -ne $length) { $size = [long]$length }
        }
        $kind = $script:WReparseKindFile
        if ($isContainer) { $kind = $script:WReparseKindDirectory }

        # InScope is only meaningful for reparse points: a plain entry is by
        # definition the entry itself, so it stays false.
        [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind $kind `
                -InScope $false -Depth $childDepth -Size $size))

        if ($isContainer) {
            $realChildCanonical = Get-WReparseCanonicalPath -Path $realChild
            if ($null -eq $realChildCanonical) { $realChildCanonical = $realChild }
            Invoke-WReparseDirectoryWalk -RealDirectory $realChildCanonical -VirtualDirectory $virtualChild `
                -Depth $childDepth -Ancestry ($Ancestry + $realChildCanonical) -State $State
        }
    }
}

function Invoke-WReparseWalk {
    # Entry point of the traversal. Returns the raw (unsorted) records, the
    # errors and the skip counter; ordering and statistics belong to the report
    # assembly step.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [int]$MaxDepth = 32,
        [switch]$Follow
    )

    # Contract section 4.3: a negative -MaxDepth behaves exactly like 0.
    $effectiveMaxDepth = [int]$MaxDepth
    if ($effectiveMaxDepth -lt 0) { $effectiveMaxDepth = 0 }

    $state = @{
        Records  = New-Object System.Collections.ArrayList
        Errors   = New-Object System.Collections.ArrayList
        Skipped  = 0
        Root     = $null
        Follow   = [bool]$Follow.IsPresent
        MaxDepth = $effectiveMaxDepth
    }

    $canonicalRoot = Get-WReparseCanonicalPath -Path $Root
    if ($null -eq $canonicalRoot) {
        # Contract section 7: the root string cannot be canonicalised.
        Add-WReparseError -State $state -RelativePath '.' -Code 'invalid_argument' `
            -Message 'The scan root could not be canonicalised.'
        return [pscustomobject][ordered]@{
            Root    = [string]$Root
            Records = @()
            Errors  = @($state.Errors.ToArray())
            Skipped = 0
        }
    }

    if (-not (Test-WReparsePathExists -Path $canonicalRoot)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'not_found' `
            -Message 'The scan root does not exist.'
        return [pscustomobject][ordered]@{
            Root    = $canonicalRoot
            Records = @()
            Errors  = @($state.Errors.ToArray())
            Skipped = 0
        }
    }

    if (-not (Test-WReparseIsDirectory -Path $canonicalRoot)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'structure' `
            -Message 'The scan root is not a directory.'
        return [pscustomobject][ordered]@{
            Root    = $canonicalRoot
            Records = @()
            Errors  = @($state.Errors.ToArray())
            Skipped = 0
        }
    }

    $state.Root = $canonicalRoot
    Invoke-WReparseDirectoryWalk -RealDirectory $canonicalRoot -VirtualDirectory $canonicalRoot `
        -Depth 0 -Ancestry @($canonicalRoot) -State $state

    return [pscustomobject][ordered]@{
        Root    = $canonicalRoot
        Records = @($state.Records.ToArray())
        Errors  = @($state.Errors.ToArray())
        Skipped = [int]$state.Skipped
    }
}

# WReparse - report assembly
# Deterministic ordering, statistics and serialisation.
# Part of the WReparse implementation. See the contract under docs/
#
# Nothing in this file except Get-WReparseReport / ConvertTo-WReparseJson is
# exported (see WReparse.psm1).

function Sort-WReparseStable {
    # Bottom-up stable merge sort driven by an explicit comparison callback.
    # Sort-Object is deliberately NOT used anywhere: its default string
    # comparison is culture-aware, and on a host whose locale treats 'A'
    # (U+00C4) as a variant of 'A' it would order non-ASCII names ahead of
    # ASCII 'Z' - a different report per machine. The comparison callback only
    # ever uses ordinal comparers (see Compare-WReparsePath), and the merge is
    # stable, so equal keys keep their discovery order.
    [CmdletBinding()]
    param(
        [AllowEmptyCollection()][object[]]$Items,
        [Parameter(Mandatory = $true)][scriptblock]$Comparison
    )
    $source = @($Items)
    $count = $source.Count
    if ($count -le 1) { return @($source) }

    # Work on an indexed copy: merging swaps two buffers instead of allocating
    # per level, which keeps the sort linear in memory and independent of the
    # enumeration order.
    $buffer = New-Object System.Collections.ArrayList
    [void]$buffer.AddRange([object[]]$source)
    $width = 1
    while ($width -lt $count) {
        $merged = New-Object System.Collections.ArrayList
        for ($start = 0; $start -lt $count; $start = $start + (2 * $width)) {
            $leftIndex = $start
            $leftEnd = [Math]::Min(($start + $width), $count)
            $rightIndex = $leftEnd
            $rightEnd = [Math]::Min(($start + (2 * $width)), $count)
            while ($leftIndex -lt $leftEnd -or $rightIndex -lt $rightEnd) {
                if ($leftIndex -ge $leftEnd) {
                    [void]$merged.Add($buffer[$rightIndex]); $rightIndex++
                }
                elseif ($rightIndex -ge $rightEnd) {
                    [void]$merged.Add($buffer[$leftIndex]); $leftIndex++
                }
                else {
                    $order = [int](& $Comparison $buffer[$leftIndex] $buffer[$rightIndex])
                    if ($order -le 0) {
                        [void]$merged.Add($buffer[$leftIndex]); $leftIndex++
                    }
                    else {
                        [void]$merged.Add($buffer[$rightIndex]); $rightIndex++
                    }
                }
            }
        }
        $buffer = $merged
        $width = 2 * $width
    }
    return @($buffer.ToArray())
}

function Compare-WReparseRecordOrder {
    # Records: RelativePath only (contract section 6.1).
    [CmdletBinding()]
    param($Left, $Right)
    $leftPath = ''
    $rightPath = ''
    if ($null -ne $Left) { $leftPath = [string]$Left.RelativePath }
    if ($null -ne $Right) { $rightPath = [string]$Right.RelativePath }
    return (Compare-WReparsePath -Left $leftPath -Right $rightPath)
}

function Compare-WReparseErrorOrder {
    # Errors: RelativePath first, Code second (contract section 6.3).
    [CmdletBinding()]
    param($Left, $Right)
    $leftPath = ''
    $rightPath = ''
    $leftCode = ''
    $rightCode = ''
    if ($null -ne $Left) {
        $leftPath = [string]$Left.RelativePath
        $leftCode = [string]$Left.Code
    }
    if ($null -ne $Right) {
        $rightPath = [string]$Right.RelativePath
        $rightCode = [string]$Right.Code
    }
    $byPath = Compare-WReparsePath -Left $leftPath -Right $rightPath
    if ($byPath -ne 0) { return $byPath }
    return (Compare-WReparsePath -Left $leftCode -Right $rightCode)
}

function Get-WReparseStats {
    # Contract section 3.3: the three counters are mutually exclusive and each
    # equals the number of records of the matching Kind.
    [CmdletBinding()]
    param(
        [AllowEmptyCollection()][object[]]$Records,
        [int]$Skipped = 0,
        [int]$ErrorCount = 0
    )
    $directories = 0
    $files = 0
    $reparse = 0
    foreach ($record in @($Records)) {
        if ($null -eq $record) { continue }
        switch ([string]$record.Kind) {
            $script:WReparseKindDirectory { $directories++; break }
            $script:WReparseKindFile { $files++; break }
            $script:WReparseKindReparse { $reparse++; break }
            default { break }
        }
    }
    return (New-WReparseStats -Directories $directories -Files $files -ReparsePoints $reparse `
            -Skipped $Skipped -Errors $ErrorCount)
}

function Get-WReparseReport {
    # Contract section 2 / section 3. -Root is mandatory, -MaxDepth defaults to
    # 32 (negative values behave like 0), -Follow defaults to off.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [int]$MaxDepth = 32,
        [switch]$Follow
    )

    $walk = Invoke-WReparseWalk -Root $Root -MaxDepth $MaxDepth -Follow:$Follow

    $records = @(Sort-WReparseStable -Items @($walk.Records) `
            -Comparison { param($Left, $Right) Compare-WReparseRecordOrder -Left $Left -Right $Right } | ForEach-Object { $_ })
    $errors = @(Sort-WReparseStable -Items @($walk.Errors) `
            -Comparison { param($Left, $Right) Compare-WReparseErrorOrder -Left $Left -Right $Right } | ForEach-Object { $_ })

    $stats = Get-WReparseStats -Records $records -Skipped ([int]$walk.Skipped) -ErrorCount $errors.Count

    return (New-WReparseReport -Root ([string]$walk.Root) -Records $records -Errors $errors -Stats $stats)
}

function ConvertTo-WReparseJson {
    # Contract section 8. ConvertTo-Json with -Depth 12 so that nested report
    # data is never truncated; $null fields serialise as JSON null and empty
    # collections as [].
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Report
    )
    return ($Report | ConvertTo-Json -Depth 12)
}

